 * @param {{ status: string, dueDate: string, lines: Array, payments?: Array }} invoice - An invoice
 * @param {string} asOf - Report date (YYYY-MM-DD)
 * @returns {number} - Late fee in cents (0.04% of amount due per day overdue)
 */
export function lateFee(invoice, asOf) {
  // Skip if draft (no late fees on unissued invoices)
  if (invoice.status === 'draft') return 0;

  // Skip if not overdue
  if (!invoice.dueDate || invoice.dueDate >= asOf) return 0;

  // Calculate days overdue
  const dueDate = new Date(invoice.dueDate + 'T00:00:00Z');
  const asOfDate = new Date(asOf + 'T00:00:00Z');
  const daysOverdue = Math.floor((asOfDate - dueDate) / (1000 * 60 * 60 * 24));

  // Get amount due
  const due = balanceDue(invoice);

  // Calculate late fee: 0.04% per day
  const fee = due * (0.04 / 100) * daysOverdue;

  return roundCents(fee);
}

/**
 * Generate a dashboard with key metrics.
 * @param {Array<{ status: string, customerId: string, dueDate: string, payments?: Array }>} invoices - All invoices
 * @param {string} asOf - Report date (YYYY-MM-DD)
 * @returns {{ counts: { draft: number, issued: number, partially_paid: number, paid: number }, outstanding: number, overdue: { count: number, amount: number }, topCustomers: Array<{ customerId: string, due: number }> }}
 */
export function dashboard(invoices, asOf) {
  // Count invoices by status
  const counts = {
    draft: invoices.filter((inv) => inv.status === 'draft').length,
    issued: invoices.filter((inv) => inv.status === 'issued').length,
    partially_paid: invoices.filter((inv) => inv.status === 'partially_paid').length,
    paid: invoices.filter((inv) => inv.status === 'paid').length,
  };

  // Calculate outstanding: total due on issued or partially_paid
  const outstanding = invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .reduce((sum, inv) => sum + balanceDue(inv), 0);

  // Get overdue summary
  const overdueList = overdueInvoices(invoices, asOf);
  const overdue = {
    count: overdueList.length,
    amount: overdueList.reduce((sum, inv) => sum + inv.due, 0),
  };

  // Calculate top customers by amount due
  const customerDues = new Map();
  invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .forEach((inv) => {
      const due = balanceDue(inv);
      if (due > 0) {
        if (!customerDues.has(inv.customerId)) {
          customerDues.set(inv.customerId, 0);
        }
        customerDues.set(inv.customerId, customerDues.get(inv.customerId) + due);
      }
    });

  const topCustomers = Array.from(customerDues.entries())
    .map(([customerId, due]) => ({ customerId, due }))
    .sort((a, b) => b.due - a.due)
    .slice(0, 3);

  return { counts, outstanding, overdue, topCustomers };
}

