test('dashboard with complex mix of invoices', () => {
  const invoices = [];
  // Draft
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  invoices.push(draft.value);

  // Issued
  const issued = createAndIssueInvoice('C-001', '2025-01-16', [{ sku: 'ICON-SET', qty: 1 }]);
  invoices.push(issued);

  // Partially paid
  const partial = createAndIssueInvoice('C-002', '2025-01-17', [{ sku: 'ICON-SET', qty: 1 }]);
  const partialResult = recordPayment(partial, { amount: 500, date: '2025-01-20' });
  invoices.push(partialResult.value);

  // Paid
  const paid = createAndIssueInvoice('C-003', '2025-01-18', [{ sku: 'ICON-SET', qty: 1 }]);
