import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary, lateFee, dashboard } from '../src/reports.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

// Helper to create and issue an invoice
function createAndIssueInvoice(customerId, issueDate, lines, terms = 'NET30') {
  const draftResult = createInvoice({
    customerId,
    issueDate,
    lines,
    terms,
  });
  if (!draftResult.ok) throw new Error(`Failed to create invoice: ${draftResult.error}`);

  const issuedResult = issueInvoice(draftResult.value, []);
  if (!issuedResult.ok) throw new Error(`Failed to issue invoice: ${issuedResult.error}`);

  return issuedResult.value;
}

test('overdueInvoices returns empty array for empty list', () => {
  const r = overdueInvoices([], '2025-03-15');
  assert.equal(Array.isArray(r), true);
  assert.equal(r.length, 0);
});

test('overdueInvoices detects single overdue invoice', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  // dueDate will be 2025-01-29

  const r = overdueInvoices([invoice], '2025-02-15');
  assert.equal(r.length, 1);
  assert.equal(r[0].number, invoice.number);
  assert.equal(r[0].customerId, 'C-001');
  assert.equal(r[0].dueDate, '2025-01-29');
});

test('overdueInvoices filters out draft invoices', () => {
  const draftResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
    terms: 'NET14',
  });
  assert.equal(draftResult.ok, true);

  const r = overdueInvoices([draftResult.value], '2025-02-15');
  assert.equal(r.length, 0);
});

test('overdueInvoices filters out paid invoices', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');

  const paymentResult = recordPayment(invoice, { amount: 1127, date: '2025-01-30' });
  assert.equal(paymentResult.ok, true);
  assert.equal(paymentResult.value.status, 'paid');

  const r = overdueInvoices([paymentResult.value], '2025-02-15');
  assert.equal(r.length, 0);
});

test('overdueInvoices includes issued invoices', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  assert.equal(invoice.status, 'issued');

  const r = overdueInvoices([invoice], '2025-02-15');
  assert.equal(r.length, 1);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');

  const paymentResult = recordPayment(invoice, { amount: 500, date: '2025-01-30' });
  assert.equal(paymentResult.ok, true);
  assert.equal(paymentResult.value.status, 'partially_paid');

  const r = overdueInvoices([paymentResult.value], '2025-02-15');
  assert.equal(r.length, 1);
});

test('overdueInvoices excludes invoices with future due dates', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET30');
  // dueDate will be 2025-02-14

  const r = overdueInvoices([invoice], '2025-02-13');
  assert.equal(r.length, 0);
});

test('overdueInvoices excludes invoices with due date equal to asOf', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET30');
  // dueDate will be 2025-02-14

  const r = overdueInvoices([invoice], '2025-02-14');
  assert.equal(r.length, 0);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  // dueDate will be 2025-01-29

  const r = overdueInvoices([invoice], '2025-02-05');
  assert.equal(r.length, 1);
  assert.equal(r[0].daysOverdue, 7);
});

test('overdueInvoices calculates daysOverdue as 0 for one day overdue', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  // dueDate will be 2025-01-29

  const r = overdueInvoices([invoice], '2025-01-30');
  assert.equal(r.length, 1);
  assert.equal(r[0].daysOverdue, 1);
});

test('overdueInvoices calculates due for issued invoice', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');

  const r = overdueInvoices([invoice], '2025-02-15');
  assert.equal(r.length, 1);
  assert.equal(r[0].due, 1127);
});

test('overdueInvoices calculates due for partially_paid invoice', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');

  const paymentResult = recordPayment(invoice, { amount: 500, date: '2025-01-30' });
  assert.equal(paymentResult.ok, true);

  const r = overdueInvoices([paymentResult.value], '2025-02-15');
  assert.equal(r.length, 1);
  assert.equal(r[0].due, 627);
});

test('overdueInvoices sorts by dueDate (most overdue first)', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2025-01-10', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  const invoice2 = createAndIssueInvoice('C-001', '2025-01-20', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  const invoice3 = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');

  const r = overdueInvoices([invoice1, invoice2, invoice3], '2025-02-15');
  assert.equal(r.length, 3);
  assert.equal(r[0].dueDate, '2025-01-24');
  assert.equal(r[1].dueDate, '2025-01-29');
  assert.equal(r[2].dueDate, '2025-02-03');
});

test('overdueInvoices with multiple customers', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  const invoice2 = createAndIssueInvoice('C-002', '2025-01-20', [{ sku: 'DES-HOUR', qty: 1 }], 'NET14');

  const r = overdueInvoices([invoice1, invoice2], '2025-02-15');
  assert.equal(r.length, 2);
  assert.equal(r[0].customerId, 'C-001');
  assert.equal(r[1].customerId, 'C-002');
});

test('overdueInvoices includes invoice fields', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');

  const r = overdueInvoices([invoice], '2025-02-15');
  assert.equal(r.length, 1);
  const item = r[0];
  assert(item.number);
  assert.equal(item.customerId, 'C-001');
  assert(item.dueDate);
  assert(Number.isInteger(item.daysOverdue));
  assert(Number.isInteger(item.due));
});

test('overdueInvoices with multiple invoices, mixed status', () => {
  const issued = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');

  const invoiceForPayment = createAndIssueInvoice('C-001', '2025-01-10', [{ sku: 'DES-HOUR', qty: 1 }], 'NET14');
  const partial = recordPayment(invoiceForPayment, { amount: 500, date: '2025-01-30' });

  const r = overdueInvoices([issued, partial.value], '2025-02-15');
  assert.equal(r.length, 2);
});

test('overdueInvoices returns overdue items only', () => {
  const overdue = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  const notOverdue = createAndIssueInvoice('C-001', '2025-02-15', [{ sku: 'DES-HOUR', qty: 1 }], 'NET14');

  const r = overdueInvoices([overdue, notOverdue], '2025-02-20');
  assert.equal(r.length, 1);
  assert.equal(r[0].dueDate, overdue.dueDate);
});

test('overdueInvoices with NET30 terms (month apart)', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);
  const invoice2 = createAndIssueInvoice('C-001', '2025-02-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const r = overdueInvoices([invoice1, invoice2], '2025-03-20');
  assert.equal(r.length, 2);
  assert.equal(r[0].dueDate, invoice1.dueDate);
  assert.equal(r[1].dueDate, invoice2.dueDate);
});

test('overdueInvoices with EOM terms', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'EOM');
  // EOM dueDate will be 2025-01-31

  const r = overdueInvoices([invoice], '2025-02-15');
  assert.equal(r.length, 1);
  assert.equal(r[0].dueDate, '2025-01-31');
});

test('overdueInvoices with high amount due', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 100 }], 'NET14');

  const r = overdueInvoices([invoice], '2025-02-15');
  assert.equal(r.length, 1);
  assert(r[0].due > 100000);
});

test('overdueInvoices preserves invoice number', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');

  const r = overdueInvoices([invoice], '2025-02-15');
  assert.equal(r[0].number, invoice.number);
  assert.match(r[0].number, /^INV-2025-\d{4}$/);
});

test('overdueInvoices many overdue invoices', () => {
  const invoices = [];
  for (let i = 0; i < 10; i++) {
    const invoice = createAndIssueInvoice('C-001', `2025-0${1 + Math.floor(i / 3)}-${10 + i}`, [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
    invoices.push(invoice);
  }

  const r = overdueInvoices(invoices, '2025-04-15');
  assert(r.length > 0);
  for (let i = 0; i < r.length - 1; i++) {
    assert(r[i].dueDate <= r[i + 1].dueDate);
  }
});

test('overdueInvoices with different discount amounts', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1, discountPercent: 5 }], 'NET14');
  const invoice2 = createAndIssueInvoice('C-001', '2025-01-20', [{ sku: 'ICON-SET', qty: 1, discountPercent: 10 }], 'NET14');

  const r = overdueInvoices([invoice1, invoice2], '2025-02-15');
  assert.equal(r.length, 2);
  assert(r[0].due > 0);
  assert(r[1].due > 0);
  assert(r[0].due !== r[1].due);
});

test('overdueInvoices at exact asOf date boundary', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  // dueDate: 2025-01-29

  // On dueDate: not overdue
  const r1 = overdueInvoices([invoice], '2025-01-29');
  assert.equal(r1.length, 0);

  // One day after: overdue with 1 day
  const r2 = overdueInvoices([invoice], '2025-01-30');
  assert.equal(r2.length, 1);
  assert.equal(r2[0].daysOverdue, 1);
});

// VAT Summary Tests

test('vatSummary returns empty array for empty invoices', () => {
  const r = vatSummary([]);
  assert.equal(Array.isArray(r), true);
  assert.equal(r.length, 0);
});

test('vatSummary filters out draft invoices', () => {
  const draftResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  assert.equal(draftResult.ok, true);

  const r = vatSummary([draftResult.value]);
  assert.equal(r.length, 0);
});

test('vatSummary includes issued invoices', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);
  assert.equal(invoice.status, 'issued');

  const r = vatSummary([invoice]);
  assert(r.length > 0);
});

test('vatSummary includes partially_paid invoices', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const paymentResult = recordPayment(invoice, { amount: 500, date: '2025-01-20' });
  assert.equal(paymentResult.ok, true);

  const r = vatSummary([paymentResult.value]);
  assert(r.length > 0);
});

test('vatSummary includes paid invoices', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const paymentResult = recordPayment(invoice, { amount: 1127, date: '2025-01-20' });
  assert.equal(paymentResult.ok, true);
  assert.equal(paymentResult.value.status, 'paid');

  const r = vatSummary([paymentResult.value]);
  assert(r.length > 0);
});

test('vatSummary single line calculates base and vat', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const r = vatSummary([invoice]);
  assert.equal(r.length, 1);
  assert(r[0].rate > 0);
  assert(r[0].base > 0);
  assert(r[0].vat > 0);
});

test('vatSummary aggregates multiple lines with same rate', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [
    { sku: 'ICON-SET', qty: 1 },
    { sku: 'ICON-SET', qty: 1 },
  ]);

  const r = vatSummary([invoice]);
  assert.equal(r.length, 1);
  assert(r[0].base > 0);
  assert(r[0].vat > 0);
});

test('vatSummary aggregates multiple invoices with same rate', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);
  const invoice2 = createAndIssueInvoice('C-001', '2025-02-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const r = vatSummary([invoice1, invoice2]);
  assert.equal(r.length, 1);
  assert(r[0].base > 0);
  assert(r[0].vat > 0);
});

test('vatSummary with lines having different VAT rates', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [
    { sku: 'ICON-SET', qty: 1 },
    { sku: 'DES-HOUR', qty: 1 },
  ]);

  const r = vatSummary([invoice]);
  assert(r.length >= 1);
  for (const item of r) {
    assert(Number.isInteger(item.rate));
    assert(item.base >= 0);
    assert(item.vat >= 0);
  }
});

test('vatSummary sorts by rate descending', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);
  const invoice2 = createAndIssueInvoice('C-001', '2025-02-15', [{ sku: 'DES-HOUR', qty: 1 }]);

  const r = vatSummary([invoice1, invoice2]);
  for (let i = 0; i < r.length - 1; i++) {
    assert(r[i].rate >= r[i + 1].rate);
  }
});

test('vatSummary with invoice having discount', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [
    { sku: 'ICON-SET', qty: 1, discountPercent: 10 },
  ]);

  const r = vatSummary([invoice]);
  assert.equal(r.length, 1);
  assert(r[0].base > 0);
  assert(r[0].vat > 0);
});

test('vatSummary with multiple VAT rates', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 2 }]);
  const invoice2 = createAndIssueInvoice('C-002', '2025-02-15', [{ sku: 'DES-HOUR', qty: 5 }]);

  const r = vatSummary([invoice1, invoice2]);
  assert(r.length > 0);
  const rates = r.map((item) => item.rate);
  const uniqueRates = new Set(rates);
  assert.equal(uniqueRates.size, r.length);
});

test('vatSummary includes rate in each entry', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const r = vatSummary([invoice]);
  assert.equal(r.length, 1);
  assert('rate' in r[0]);
  assert('base' in r[0]);
  assert('vat' in r[0]);
});

test('vatSummary with complex multi-line invoice', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [
    { sku: 'ICON-SET', qty: 2, discountPercent: 5 },
    { sku: 'DES-HOUR', qty: 1 },
    { sku: 'ICON-SET', qty: 3 },
  ]);

  const r = vatSummary([invoice]);
  assert(r.length > 0);
  for (const item of r) {
    assert(item.rate >= 0);
    assert(item.base >= 0);
    assert(item.vat >= 0);
  }
});

test('vatSummary with mixed invoice statuses', () => {
  const issued = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);

  const invoiceForPayment = createAndIssueInvoice('C-001', '2025-02-15', [{ sku: 'DES-HOUR', qty: 1 }]);
  const partial = recordPayment(invoiceForPayment, { amount: 500, date: '2025-02-20' });

  const r = vatSummary([issued, partial.value]);
  assert(r.length > 0);
});

test('vatSummary zero VAT rate included', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [
    { sku: 'ICON-SET', qty: 1 },
  ]);

  // Check if any line has 0 VAT rate by examining the invoice
  const hasZeroVat = invoice.lines.some((line) => line.vatRate === 0);
  const r = vatSummary([invoice]);

  // If invoice has a 0% VAT line, it should be in the summary
  if (hasZeroVat) {
    const zeroRateEntry = r.find((item) => item.rate === 0);
    if (zeroRateEntry) {
      assert(zeroRateEntry.base >= 0);
      assert.equal(zeroRateEntry.vat, 0);
    }
  }
});

test('vatSummary base and vat are integers', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [
    { sku: 'ICON-SET', qty: 1 },
    { sku: 'DES-HOUR', qty: 1 },
  ]);

  const r = vatSummary([invoice]);
  for (const item of r) {
    assert(Number.isInteger(item.base), 'base must be an integer');
    assert(Number.isInteger(item.vat), 'vat must be an integer');
  }
});

test('vatSummary vat is less than or equal to base (typical case)', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 10 }]);

  const r = vatSummary([invoice]);
  for (const item of r) {
    // VAT is typically much less than base (unless VAT rate > 100%, which is rare)
    if (item.rate <= 100) {
      assert(item.vat <= item.base * 1.5, `VAT should be reasonable relative to base`);
    }
  }
});

test('vatSummary with high quantity items', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 100 }]);

  const r = vatSummary([invoice]);
  assert.equal(r.length, 1);
  assert(r[0].base > 10000);
  assert(r[0].vat > 0);
});

test('vatSummary report totals', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }]);
  const invoice2 = createAndIssueInvoice('C-001', '2025-02-15', [{ sku: 'ICON-SET', qty: 2 }]);

  const r = vatSummary([invoice1, invoice2]);
  const totalBase = r.reduce((sum, item) => sum + item.base, 0);
  const totalVat = r.reduce((sum, item) => sum + item.vat, 0);

  assert(totalBase > 0);
  assert(totalVat > 0);
});

// Late Fee Tests

test('lateFee returns 0 for invoice not overdue', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET30');
  // dueDate will be 2025-02-14

  const fee = lateFee(invoice, '2025-02-14');
  assert.equal(fee, 0);
});

test('lateFee returns 0 for invoice on due date', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  // dueDate will be 2025-01-29

  const fee = lateFee(invoice, '2025-01-29');
  assert.equal(fee, 0);
});

test('lateFee returns 0 for paid invoice', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');

  const paymentResult = recordPayment(invoice, { amount: 1127, date: '2025-02-05' });
  assert.equal(paymentResult.ok, true);
  assert.equal(paymentResult.value.status, 'paid');

  const fee = lateFee(paymentResult.value, '2025-02-10');
  assert.equal(fee, 0);
});

test('lateFee calculates fee for small overdue period', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  // dueDate will be 2025-01-29, due amount 1127

  const fee = lateFee(invoice, '2025-02-15');
  // 17 days overdue: 1127 * 0.0004 * 17 = 7.6636, rounds to 8
  assert(fee > 0);
});

test('lateFee calculates fee for medium overdue period', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  // dueDate will be 2025-01-29

  const fee = lateFee(invoice, '2025-03-05');
  // 35 days overdue: 1127 * 0.0004 * 35 = 15.778, rounds to 16
  assert(fee > 0);
});

test('lateFee calculates fee for long overdue period', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  // dueDate will be 2025-01-29

  const fee = lateFee(invoice, '2025-04-10');
  // 71 days overdue: 1127 * 0.0004 * 71 = 32.0636, rounds to 32
  assert(fee > 0);
});

test('lateFee for partially paid invoice', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');

  const paymentResult = recordPayment(invoice, { amount: 500, date: '2025-01-30' });
  assert.equal(paymentResult.ok, true);

  const fee = lateFee(paymentResult.value, '2025-03-01');
  assert(fee > 0);
  // Due = 1127 - 500 = 627
  // Days overdue from 2025-01-29 to 2025-03-01 = 31 days
  // Fee = 627 * 0.0004 * 31 = 7.7748, rounds to 8
});

test('lateFee is integer cents', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');

  const fee = lateFee(invoice, '2025-02-10');
  assert(Number.isInteger(fee), 'fee must be an integer');
});

test('lateFee with different amounts due', () => {
  const invoice1 = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  const invoice2 = createAndIssueInvoice('C-001', '2025-01-20', [{ sku: 'ICON-SET', qty: 5 }], 'NET14');

  const fee1 = lateFee(invoice1, '2025-02-05');
  const fee2 = lateFee(invoice2, '2025-02-05');

  assert(fee1 > 0);
  assert(fee2 > fee1);
});

test('lateFee with discounted invoice', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [
    { sku: 'ICON-SET', qty: 1, discountPercent: 10 },
  ], 'NET14');

  const fee = lateFee(invoice, '2025-02-10');
  assert(fee > 0);
});

test('lateFee increases with more days overdue', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  // dueDate will be 2025-01-29

  const fee15 = lateFee(invoice, '2025-02-13');
  const fee35 = lateFee(invoice, '2025-03-05');
  const fee70 = lateFee(invoice, '2025-04-09');

  assert(fee15 > 0);
  assert(fee35 > fee15);
  assert(fee70 > fee35);
});

test('lateFee for issued invoice', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  assert.equal(invoice.status, 'issued');

  const fee = lateFee(invoice, '2025-02-10');
  assert(fee > 0);
});

test('lateFee for partially_paid invoice', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');

  const paymentResult = recordPayment(invoice, { amount: 600, date: '2025-01-30' });
  assert.equal(paymentResult.ok, true);
  assert.equal(paymentResult.value.status, 'partially_paid');

  const fee = lateFee(paymentResult.value, '2025-02-10');
  assert(fee > 0);
});

test('lateFee does not double-charge for same day', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET14');
  // dueDate will be 2025-01-29

  const fee = lateFee(invoice, '2025-01-29');
  assert.equal(fee, 0);
});

test('lateFee with multiple lines', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [
