test('lateFee calculation precision', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 2 }], 'NET14');

  const fee1 = lateFee(invoice, '2025-01-30');
  const fee2 = lateFee(invoice, '2025-01-31');

  // Each additional day should increase fee
  assert(fee2 > fee1);
});

test('lateFee returns 0 for draft invoice', () => {
  const draftResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
    terms: 'NET14',
  });
  assert.equal(draftResult.ok, true);

  // Draft invoice has a dueDate but no status (status is 'draft'), so balanceDue would be 0
  const fee = lateFee(draftResult.value, '2025-02-10');
  // balanceDue on draft returns 0 since there are no payments, so fee should be 0
  assert.equal(fee, 0);
});

test('lateFee with high amount due', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 100 }], 'NET14');

  const fee = lateFee(invoice, '2025-02-10');
  assert(fee > 0);
  assert(Number.isInteger(fee));
});

test('lateFee zero for future date edge case', () => {
  const invoice = createAndIssueInvoice('C-001', '2025-01-15', [{ sku: 'ICON-SET', qty: 1 }], 'NET30');

  const fee = lateFee(invoice, '2025-02-15');
  assert.equal(fee, 0);
});

